using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _sut;

    public NotificationServiceTests()
    {
        _sut = new NotificationService();
        // Drain any leftovers from previous tests (static queue)
        while (_sut.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        // Drain queue to avoid cross-test interference
        while (_sut.ReceiveNotification() != null) { }
        _sut.Dispose();
    }

    [Fact]
    public void SendNotification_WithDisplayName_EnqueuesNotificationWithCorrectMessage()
    {
        // Act
        _sut.SendNotification("Course", "101", "Chemistry", EntityOperation.CREATE, "Admin");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Course", notification.EntityType);
        Assert.Equal("101", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Equal("New Course 'Chemistry' has been created", notification.Message);
        Assert.Equal("Admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesIdInMessage()
    {
        // Act
        _sut.SendNotification("Student", "42", EntityOperation.CREATE, "Admin");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("New Student (ID: 42) has been created", notification.Message);
        Assert.Equal("Admin", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_WithNullUserName_DefaultsToSystem()
    {
        // Act
        _sut.SendNotification("Student", "1", EntityOperation.CREATE);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Theory]
    [InlineData(EntityOperation.CREATE, "New Course 'Physics' has been created")]
    [InlineData(EntityOperation.UPDATE, "Course 'Physics' has been updated")]
    [InlineData(EntityOperation.DELETE, "Course 'Physics' has been deleted")]
    public void SendNotification_DifferentOperations_GeneratesCorrectMessage(EntityOperation operation, string expectedMessage)
    {
        // Act
        _sut.SendNotification("Course", "200", "Physics", operation, "TestUser");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal(expectedMessage, notification.Message);
        Assert.Equal(operation.ToString(), notification.Operation);
    }

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        var notification = _sut.ReceiveNotification();
        Assert.Null(notification);
    }

    [Fact]
    public void ReceiveNotification_PopulatedQueue_ReturnsAndRemoves()
    {
        // Arrange
        _sut.SendNotification("Student", "1", "Alice", EntityOperation.CREATE);
        _sut.SendNotification("Student", "2", "Bob", EntityOperation.CREATE);

        // Act
        var first = _sut.ReceiveNotification();
        var second = _sut.ReceiveNotification();
        var third = _sut.ReceiveNotification();

        // Assert
        Assert.NotNull(first);
        Assert.Contains("Alice", first.Message);
        Assert.NotNull(second);
        Assert.Contains("Bob", second.Message);
        Assert.Null(third); // queue should be empty
    }

    [Fact]
    public void SendNotification_FifoOrder_IsPreserved()
    {
        // Arrange
        _sut.SendNotification("A", "1", "First", EntityOperation.CREATE);
        _sut.SendNotification("B", "2", "Second", EntityOperation.UPDATE);
        _sut.SendNotification("C", "3", "Third", EntityOperation.DELETE);

        // Act & Assert
        var n1 = _sut.ReceiveNotification();
        Assert.Equal("A", n1!.EntityType);

        var n2 = _sut.ReceiveNotification();
        Assert.Equal("B", n2!.EntityType);

        var n3 = _sut.ReceiveNotification();
        Assert.Equal("C", n3!.EntityType);
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        // MarkAsRead is a no-op, but should not throw
        var exception = Record.Exception(() => _sut.MarkAsRead(42));
        Assert.Null(exception);
    }

    [Fact]
    public void Dispose_DoesNotThrow()
    {
        var service = new NotificationService();
        var exception = Record.Exception(() => service.Dispose());
        Assert.Null(exception);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_NullDisplayName_UsesIdFormat()
    {
        _sut.SendNotification("Department", "5", null, EntityOperation.UPDATE, "User1");

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Department (ID: 5) has been updated", notification.Message);
    }

    [Fact]
    public void SendNotification_WithEmptyDisplayName_UsesIdFormat()
    {
        _sut.SendNotification("Department", "5", "  ", EntityOperation.DELETE, "User1");

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Department (ID: 5) has been deleted", notification.Message);
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToRecentTime()
    {
        var before = DateTime.Now;
        _sut.SendNotification("Student", "1", EntityOperation.CREATE);
        var after = DateTime.Now;

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.InRange(notification.CreatedAt, before, after);
    }

    [Fact]
    public void SendNotification_SetsIsReadToFalse()
    {
        _sut.SendNotification("Student", "1", EntityOperation.CREATE);

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.False(notification.IsRead);
    }
