    [Fact]
    public void DeleteConfirmed_CourseWithImage_DeletesFile()
    {
        // Create a file to be deleted
        var uploadsPath = Path.Combine(_tempPath, "Uploads", "TeachingMaterials");
        Directory.CreateDirectory(uploadsPath);
        var fileName = "test_image.jpg";
        var filePath = Path.Combine(uploadsPath, fileName);
        File.WriteAllText(filePath, "fake image content");

        var course = _context.Courses.First();
        course.TeachingMaterialImagePath = $"/Uploads/TeachingMaterials/{fileName}";
        _context.SaveChanges();

        _controller.DeleteConfirmed(course.CourseID);

        Assert.False(File.Exists(filePath));
    }

    // ---- Helpers ----

    private static Mock<IFormFile> CreateMockFormFile(string fileName, long length, bool hasContent = false)
    {
        var mock = new Mock<IFormFile>();
        mock.Setup(f => f.FileName).Returns(fileName);
        mock.Setup(f => f.Length).Returns(length);

        if (hasContent)
        {
            var ms = new MemoryStream(new byte[length < 4096 ? length : 4096]);
            mock.Setup(f => f.CopyTo(It.IsAny<Stream>()))
                .Callback<Stream>(s => ms.CopyTo(s));
        }

        return mock;
    }
}

