    [Fact]
    public void SendNotification_SetsIsReadToFalse()
    {
        _sut.SendNotification("Student", "1", EntityOperation.CREATE);

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void SendNotification_QueueCapEnforced_OldestDroppedWhenExceeding500()
    {
        // Fill beyond the cap of 500
        for (int i = 0; i < 510; i++)
        {
            _sut.SendNotification("Item", i.ToString(), $"Item{i}", EntityOperation.CREATE);
        }

        // Drain the queue and count
        int count = 0;
        while (_sut.ReceiveNotification() != null)
        {
            count++;
        }

        // Should be at most 500 (the cap)
        Assert.True(count <= 500, $"Expected at most 500 notifications but got {count}");
    }
}

